oxy_webhelp_navlinks = {"service_account-d39307e12630":{"topics":[{"title":"<span class=\"ph\">RSC<\/span> service accounts for automation","shortdesc":"<p class=\"shortdesc\">Information about using <span class=\"ph\">RSC<\/span> service accounts to securely automate API access with CDM 9.4 and later.<\/p>","href":"saas\/service_accounts_automation.html","attributes":{"data-id":"service_accounts_automation"},"menu":{"hasChildren":false},"tocID":"service_accounts_automation-d39307e12646","topics":[]},{"title":"API access with service accounts","shortdesc":"<p class=\"shortdesc\">Service accounts enable client applications and other services to invoke the <span class=\"ph\">RSC<\/span> APIs securely.<\/p>","href":"saas\/api_access_with_service_accounts.html","attributes":{"data-id":"api_access_with_service_accounts"},"menu":{"hasChildren":false},"tocID":"api_access_with_service_accounts-d39307e12662","topics":[]},{"title":"Guidelines for adding service accounts","shortdesc":"<p class=\"shortdesc\">Guidelines to optimize the security of the client application represented by a         service account.<\/p>","href":"saas\/guidelines_for_adding_service_accounts.html","attributes":{"data-id":"guidelines_for_adding_service_accounts"},"menu":{"hasChildren":false},"tocID":"guidelines_for_adding_service_accounts-d39307e12676","next":"guidelines_for_adding_service_accounts-d39307e12676"},{"title":"Adding a service account","shortdesc":"<p class=\"shortdesc\">Add a service account in <span class=\"ph\">RSC<\/span> to generate client credentials and enable         client-side applications to authenticate to <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/adding_a_service_account.html","attributes":{"data-id":"adding_a_service_account"},"menu":{"hasChildren":false},"tocID":"adding_a_service_account-d39307e12698","topics":[]},{"title":"Obtaining an access token","shortdesc":"<p class=\"shortdesc\">Obtain an access token by sending a request to the authorization server with service         account client credentials<span class=\"ph\"> or personal access token             credentials<\/span>. This access token is required to invoke the <span class=\"ph\">RSC<\/span>         APIs.<\/p>","href":"saas\/using_client_creds_to_obtain_at.html","attributes":{"data-id":"using_client_creds_to_obtain_at"},"menu":{"hasChildren":false},"tocID":"using_client_creds_to_obtain_at-d39307e12715","topics":[]},{"title":"Service account modification","shortdesc":"<p class=\"shortdesc\">Only the description of a service account can be modified.<\/p>","href":"saas\/service_account_modification.html","attributes":{"data-id":"service_account_modification"},"menu":{"hasChildren":false},"tocID":"service_account_modification-d39307e12732","topics":[]},{"title":"Rotating the client secret","shortdesc":"<p class=\"shortdesc\">Generate a client secret for a service account and invalidate the old         secret.<\/p>","href":"saas\/rotating_the_client_secret.html","attributes":{"data-id":"rotating_the_client_secret"},"menu":{"hasChildren":false},"tocID":"rotating_the_client_secret-d39307e12743","topics":[]},{"title":"Deleting a service account","shortdesc":"<p class=\"shortdesc\">Delete a service account if it is not required to represent any client application         that needs to access the <span class=\"ph\">RSC<\/span> APIs.<\/p>","href":"saas\/deleting_a_service_account.html","attributes":{"data-id":"deleting_a_service_account"},"menu":{"hasChildren":false},"tocID":"deleting_a_service_account-d39307e12754","topics":[]}]}};